using System.IO;
using System.Linq;
using System.Collections;
using UnityEditor;
using UnityEngine;
using UnityEngine.EventSystems;
[InitializeOnLoad] public static class StorybookMapMotionValidation
{
 const string Out=StorybookMapMotionAuthoring.Out;static bool running;
 static StorybookMapMotionValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("MAP_MOTION_QA",false)){SessionState.SetBool("MAP_MOTION_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");UnityEditor.SceneManagement.EditorSceneManager.OpenScene(EditorBuildSettings.scenes.First(s=>s.enabled).path);File.WriteAllText(Out+"validation.txt","");SessionState.SetBool("MAP_MOTION_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("MAP_MOTION_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;GameManager.single.StartCoroutine(Run());}}
 static void Check(bool value,string text)=>File.AppendAllText(Out+"validation.txt",(value?"PASS ":"FAIL ")+text+"\n");
 static void Shot(string name){var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+name+".png",t.EncodeToPNG());Object.Destroy(t);}
 static IEnumerator Run(){var intro=Object.FindAnyObjectByType<CursedBookIntro>();while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(.5f);foreach(var d in Object.FindObjectsByType<DebugMenu>(FindObjectsInactive.Include,FindObjectsSortMode.None))d.enabled=false;var dev=Object.FindAnyObjectByType<DeveloperOverlayUI>();if(dev)dev.gameObject.SetActive(false);var gc=GameplayCanvas.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);gc.GetComponent<StorybookDailyReward>().enabled=false;TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();Router.single.MapButton();yield return new WaitForSecondsRealtime(2);
 var ui=Object.FindAnyObjectByType<StorybookMapUI>();Check(ui,"Map entered");if(!ui){EditorApplication.isPlaying=false;yield break;}
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);yield return new WaitForSecondsRealtime(.3f);var n=ui.nodes[1];var f=n.button.GetComponent<ShelterButtonFeedback>();var label=(RectTransform)n.label.transform;var corners=new Vector3[4];label.GetWorldCorners(corners);var before=n.seal.transform.localScale;var p=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left};f.OnPointerDown(p);Canvas.ForceUpdateCanvases();var after=new Vector3[4];label.GetWorldCorners(after);Check(corners.SequenceEqual(after)&&n.button.transform.localScale==Vector3.one,"Label and root remain still "+size);Check(n.seal.transform.localScale==before*.9f,"Only icon scales "+size);yield return new WaitForEndOfFrame();Shot("icon-pressed-"+size.x+"x"+size.y);f.OnPointerUp(p);Check(n.seal.transform.localScale==before,"Icon restores "+size);
 ui.SelectNode(1);var m=ui.detailMotion;float start=m.content.anchoredPosition.y;Check(start<=-m.content.rect.height&&!m.group.blocksRaycasts&&m.group.alpha==1,"Whole card starts below clipped edge without fade "+size);yield return new WaitForSecondsRealtime(.12f);Check(m.content.anchoredPosition.y>start&&m.content.anchoredPosition.y<0,"Card rises visibly "+size);yield return new WaitForEndOfFrame();Shot("detail-rising-"+size.x+"x"+size.y);ui.SelectNode(2);Check(m.content.anchoredPosition.y<=-m.content.rect.height,"Rapid reselection restarts rise "+size);yield return new WaitForSecondsRealtime(.5f);Check(m.content.anchoredPosition==Vector2.zero&&m.group.blocksRaycasts&&m.group.interactable,"Card settles with input restored "+size);yield return new WaitForEndOfFrame();Shot("detail-settled-"+size.x+"x"+size.y);
 }
 ui.SelectNode(1);ui.gameObject.SetActive(false);Check(ui.detailMotion.content.anchoredPosition==Vector2.zero,"Leaving during motion resets position");ui.gameObject.SetActive(true);yield return null;File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;
 }
}
